package org.apache.commons.cli;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.cli.Option;
import org.apache.commons.cli.OptionBuilder;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.fail;

public class OptionBuilder_create_TriageGen1Test {

    @Before
    public void setUp() {
        // Reset OptionBuilder properties before each test
        OptionBuilder.reset();
    }

    @Test
    public void testCreate_ValidOption() throws IllegalArgumentException {
        String opt = "testOption";
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Option description should match", "testOption", option.getOpt());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_NullOption() throws IllegalArgumentException {
        OptionBuilder.create((String) null);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_EmptyOption() throws IllegalArgumentException {
        OptionBuilder.create("");
    }

    @Test
    public void testCreate_WithLongOpt() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withLongOpt("longOption");
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Long option should be set", "longOption", option.getLongOpt());
    }

    @Test
    public void testCreate_WithDescription() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withDescription("A test option");
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Description should be set", "A test option", option.getDescription());
    }

    @Test
    public void testCreate_IsRequired() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.isRequired();
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertTrue("Option should be required", option.isRequired());
    }

    @Test
    public void testCreate_HasArg() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.hasArg();
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertTrue("Option should have an argument", option.hasArg());
    }

    @Test
    public void testCreate_HasArgs() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.hasArgs(2);
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Option should have 2 arguments", 2, option.getArgs());
    }

    @Test
    public void testCreate_HasOptionalArg() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.hasOptionalArg();
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertTrue("Option should have an optional argument", option.hasOptionalArg());
    }

    @Test
    public void testCreate_WithArgName() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withArgName("argName");
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Argument name should be set", "argName", option.getArgName());
    }

    @Test
    public void testCreate_WithValueSeparator() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withValueSeparator(':');
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Value separator should be set", ':', option.getValueSeparator());
    }

    @Test
    public void testCreate_WithType() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withType(String.class);
        Option option = OptionBuilder.create(opt);

        assertNotNull("Option should not be null", option);
        assertEquals("Type should be set", String.class, option.getType());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreate_InvalidType() throws IllegalArgumentException {
        String opt = "testOption";
        OptionBuilder.withType((Class<?>) null);
        OptionBuilder.create(opt);
    }
}
